  scenario("stop-only-no-attacker-refused-before-registration",()->{var mc=environment();var z=zombie(mc,2);publish(mc,z,false);ok(rejects(()->admit(mc,z,request(true))).equals("route_spatial_stop_only_attacker_required"),"flag never manufactures attacker");ok(ClientActions.active==null&&ClientActions.ACTIONS.active()==null&&mc.player.yaw==0&&ScopedLocalSegmentMovement.neutral(mc.player.input),"no registry/input/view effect");});
